import {installLanguageSwitch} from './i18n.js';
import {handleMessage,missing,lotSummary,poolLots,compare,demoCosts,demoOrder,classify} from './core.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),brl=n=>'R$ '+n.toFixed(2),key='harvestlink-v1';
const modelResponse=await fetch('/model.json'),modelText=await modelResponse.text(),model=JSON.parse(modelText),modelBytes=new TextEncoder().encode(modelText).length;
const defaults=()=>({lots:[],session:{draft:{}},chat:[],choices:[],handovers:[],benchmarks:[],costs:{...demoCosts},starts:0});
let state;try{state=JSON.parse(localStorage.getItem(key))||defaults();}catch{state=defaults();}
const restored={lots:state.lots.length,choices:state.choices.length};state.starts++;persist();
function persist(){localStorage.setItem(key,JSON.stringify(state));}
function toast(text){$('#toast').textContent=text;}
function download(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function card(text){return `<div class="card">${esc(text)}</div>`;}
function render(){
 $('#lot-count').textContent=state.lots.length;
 $('#chat').innerHTML=state.chat.length?state.chat.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join(''):card('Olá! Registre um lote de tomate. Você revisa tudo antes de confirmar.');$('#chat').scrollTop=$('#chat').scrollHeight;
 const d=state.session.draft||{};
 $('#draft').innerHTML=Object.keys(d).length?card(Object.entries(d).map(([k,v])=>`${k}: ${v}`).join(' • ')):card('Nenhum rascunho ainda.');
 $('#confirm-lot').disabled=missing(d).length!==0&&!state.session.pendingChoice;
 $('#lots').innerHTML=state.lots.map(l=>card(lotSummary(l)+' Confirmado '+l.confirmedAt)).join('')||card('Nenhum lote confirmado.');
 $('#buyer-lots').innerHTML=state.lots.map(l=>card(lotSummary(l,'en'))).join('')||card('No confirmed availability yet.');
 $('#order').innerHTML=card(`${demoOrder.label}. ${demoOrder.buyer}. ${demoOrder.quantityKg} kg grade A tomatoes; harvest ${demoOrder.earliest} to ${demoOrder.latest}; GYD ${demoOrder.priceGydKg}/kg.`);
 const pool=poolLots(state.lots);$('#pool').innerHTML=card(`${pool.matched?'MATCHED PROPOSAL':'INCOMPLETE'} · ${pool.quantityKg}/${demoOrder.quantityKg} kg · Shortfall ${pool.shortfallKg} kg`)+pool.allocations.map(a=>card(`${a.lot.farmer} · ${a.kg} kg · lot ${a.lot.id.slice(0,8)}`)).join('');
 $('#choice-lot').innerHTML=pool.allocations.map(a=>`<option value="${esc(a.lot.id)}">${esc(a.lot.farmer)} · ${a.kg} kg</option>`).join('');
 $('#save-choice').disabled=!pool.matched;
 $('#cost-source').textContent=`${state.costs.source}. As of ${state.costs.asOf}; valid until ${state.costs.validUntil}. No trade clearance implied.`;
 const c=compare(pool,state.costs);$('#comparison').innerHTML=`<h2>Mesmo volume. Duas opções.</h2><p>${c.q} kg supplied · ${c.billedKg.toFixed(1)} kg billed after ${state.costs.lossPercent}% assumed loss</p><div class="totals"><div>Local líquido<b>${brl(c.localNet)}</b></div><div>Proposta líquida<b>${brl(c.crossNet)}</b></div></div><p>Gross: GYD ${c.grossGyd.toFixed(2)} ÷ ${state.costs.gydPerBrl} GYD/BRL = ${brl(c.grossBrl)}</p><table><thead><tr><th>Cross-border deduction</th><th>BRL</th></tr></thead><tbody>${c.rows.map(([name,value])=>`<tr><td>${esc(name)}</td><td>${brl(value)}</td></tr>`).join('')}<tr><th>Total deductions</th><th>${brl(c.totalCosts)}</th></tr></tbody></table><p>Local transport: ${brl(state.costs.localTransportBrlKg)}/kg. Cross-border allowance is illustrative and may omit actual charges.</p><table><thead><tr><th>Farmer</th><th>kg</th><th>Local net</th><th>Proposal net</th></tr></thead><tbody>${c.farmers.map(f=>`<tr><td>${esc(f.name)}</td><td>${f.kg}</td><td>${brl(f.localNet)}</td><td>${brl(f.crossNet)}</td></tr>`).join('')}</tbody></table>${!pool.matched?'<p class="notice">Order incomplete. Choice disabled until the full order is matched.</p>':''}${c.expired?'<p class="notice">Cost assumptions expired. Update dates before recording a choice.</p>':''}`;
 $('#choices').innerHTML=state.choices.map(c=>card(`${c.farmer} · ${c.choice} · ${c.quantityKg} kg · snapshot ${c.createdAt} · saved on device`)).join('');
 $('#handover-record').innerHTML=state.handovers.length?`<pre>${esc(JSON.stringify(state.handovers.at(-1),null,2))}</pre>`:card('No exporter handover saved.');
 $('#persistence').textContent=`Launch ${state.starts}: restored ${restored.lots} lots and ${restored.choices} choices. Device storage survives app restarts; clearing browser data removes it. Export a backup.`;
 $('#metrics').textContent=state.benchmarks.length?JSON.stringify(state.benchmarks.at(-1),null,2):`Model: ${model.name}\nModel file: ${modelBytes} bytes\nBenchmark not run on this device.`;
}
function submit(text){const start=performance.now(),result=handleMessage(text,state.session,model,{lots:state.lots,choices:state.choices,costs:state.costs}),elapsed=performance.now()-start;state.session=result.session;state.chat.push({role:'user',text},{role:'assistant',text:result.reply});if(result.lot)state.lots.push(result.lot);if(result.choice)state.choices.push(result.choice);persist();render();$('#inference').textContent=`${model.name} · ${modelBytes} bytes · ${elapsed.toFixed(2)} ms · intent ${result.intent?.intent||'confirmation'} · local JS, zero inference requests`;}
$('#message-form').onsubmit=e=>{e.preventDefault();try{submit($('#message').value);$('#message').value='';}catch(e){toast(e.message);}};
document.querySelectorAll('[data-command]').forEach(button=>button.onclick=()=>submit(button.dataset.command));
document.querySelectorAll('[data-channel]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-channel]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelector('.messenger').dataset.channel=button.dataset.channel;$('#channel-label').textContent=button.dataset.channel==='sms'?'SMS · prévia':'WhatsApp · prévia';});
$('#sample').onclick=()=>{$('#message').value='Sou Ana, tenho 120 kg de tomate, classe A';};
$('#confirm-lot').onclick=()=>submit('CONFIRMO');
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==b.dataset.tab);document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('active',n===b));});
$('#match').onclick=()=>{render();toast('Compatibility checked: crop, grade, harvest window and unreserved quantity. Proposal only.');};
const costFields={asOf:'Data dos custos',validUntil:'Válido até',gydPerBrl:'GYD por 1 BRL',localTransportBrlKg:'Transporte local BRL/kg',crossTransportBrlKg:'Transporte da proposta BRL/kg',packagingBrlKg:'Embalagem BRL/kg',handlingBrlKg:'Manuseio BRL/kg',feePercent:'Taxa de coordenação %',lossPercent:'Perda prevista %',tradeAllowanceBrl:'Reserva comercial BRL/pedido'};
$('#cost-form').innerHTML=Object.entries(costFields).map(([k,v])=>`<label for="cost-${k}">${v}</label><input id="cost-${k}" type="${['asOf','validUntil'].includes(k)?'date':'number'}" min="0" step="any" value="${esc(state.costs[k])}">`).join('');
$('#recalculate').onclick=()=>{try{const next={...state.costs};for(const k of Object.keys(costFields))next[k]=['asOf','validUntil'].includes(k)?$('#cost-'+k).value:Number($('#cost-'+k).value);if(!next.asOf||!next.validUntil||next.validUntil<next.asOf)throw Error('Datas inválidas.');compare(poolLots(state.lots),next);state.costs=next;persist();render();toast('Custos atualizados. Escolhas anteriores mantêm o snapshot original.');}catch(e){toast(e.message);}};
$('#save-choice').onclick=()=>{try{if(!$('#choice-confirm').checked)throw Error('Confirme que leu os custos.');const pool=poolLots(state.lots),comparison=compare(pool,state.costs),a=pool.allocations.find(a=>a.lot.id===$('#choice-lot').value);if(!pool.matched||!a||comparison.expired)throw Error('Pedido incompleto ou custos vencidos.');if(state.choices.some(c=>c.lotId===a.lot.id))throw Error('Este lote já tem uma escolha registrada.');state.choices.push({id:crypto.randomUUID(),lotId:a.lot.id,farmer:a.lot.farmer,quantityKg:a.kg,choice:$('#choice').value,orderId:demoOrder.id,createdAt:new Date().toISOString(),humanConfirmed:true,costSnapshot:{...state.costs},orderSnapshot:{...demoOrder},comparisonSnapshot:comparison,status:'awaiting buyer confirmation and trade-requirement checks',synced:false});persist();render();$('#choice-confirm').checked=false;toast('Escolha salva neste dispositivo. Nenhuma remessa autorizada.');}catch(e){toast(e.message);}};
$('#export-summary').onclick=()=>download('harvestlink-buyer-proposal.json',{order:demoOrder,lots:state.lots.map(l=>({id:l.id,summary:lotSummary(l,'en')})),pool:poolLots(state.lots),status:'awaiting buyer confirmation and trade-requirement checks',templateReview:'Controlled templates v1; bilingual human sign-off pending'});
$('#create-handover').onclick=()=>{const exporter=$('#exporter').value.trim();if(!exporter)return toast('Enter an exporter or coordinator name.');const selected=state.choices.filter(c=>c.choice==='cross-border-proposal');if(!selected.length)return toast('At least one farmer must explicitly select the proposal first.');state.handovers.push({id:crypto.randomUUID(),createdAt:new Date().toISOString(),exporter,notes:$('#handover-note').value,order:demoOrder,farmerChoices:selected,lots:state.lots.filter(l=>selected.some(c=>c.lotId===l.id)),quantityKg:selected.reduce((s,c)=>s+c.quantityKg,0),fullFarmerConsent:selected.reduce((s,c)=>s+c.quantityKg,0)===demoOrder.quantityKg,status:'awaiting buyer confirmation and trade-requirement checks',checks:{buyerConfirmation:'pending',tradeRequirements:'unchecked',exporterEligibility:'unchecked',quality:'unconfirmed',transport:'unconfirmed',payment:'unconfirmed'},dispatchAuthorized:false});persist();render();toast('Handover saved. Only consenting farmers included.');};
$('#download-handover').onclick=()=>state.handovers.length?download('harvestlink-exporter-handover.json',state.handovers.at(-1)):toast('Save a handover first.');
$('#benchmark').onclick=()=>{const samples=['Sou Ana, tenho 120 kg de tomate, classe A','Quero comparar ganhos da venda local','confirmo minha colheita','cancelar lote'];const times=[];for(let i=0;i<20;i++)classify(samples[i%4],model);for(let i=0;i<100;i++){const t=performance.now();handleMessage(samples[i%4],{draft:{}},model);times.push(performance.now()-t);}times.sort((a,b)=>a-b);const physical=$('#physical-device').checked;state.benchmarks.push({recordedAt:new Date().toISOString(),model:model.name,modelBytes,samples:100,warmup:20,p50Ms:times[49],p95Ms:times[94],maxMs:times[99],measurement:'intent classification + field extraction + response generation; excludes rendering',device:$('#device').value||'unspecified',physicalAndroidSelfReported:physical,airplaneModeSelfReported:$('#airplane-attest').checked,browserReportsOnline:navigator.onLine,userAgent:navigator.userAgent,proofType:physical?'self-reported device run; external video still required':'browser measurement — not Android proof'});persist();render();toast('Benchmark saved.');};
$('#export-evidence').onclick=()=>download('harvestlink-evidence.json',{...state,modelBytes,exportedAt:new Date().toISOString(),proofLimitations:['No physical airplane-mode proof from browser alone','Provider accepted messages are not delivery proof','Template bilingual reviewer sign-off pending','Prices/orders/costs/FX are demonstration assumptions']});
async function api(path,method='GET',body){const token=$('#api-key').value;if(!token)throw Error('Enter operator API key.');const response=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed');return result;}
$('#sync').onclick=async()=>{try{const result=await api('sync','POST',{lots:state.lots,choices:state.choices,handovers:state.handovers});toast(`Synced ${result.lots} lots. Explicit online sync completed.`);}catch(e){toast(e.message);}};
$('#load-messages').onclick=async()=>{try{const data=await api('messages');$('#messaging-status').textContent=data.configured?'Twilio configured. Provider evidence below.':'Provider not configured. No real exchange yet.';$('#provider-messages').innerHTML=data.messages.map(m=>card(`${m.kind} · ${m.sid} · ${m.status||''} · ${m.body||m.reply||''} · ${m.at}`)).join('')||card('No provider messages recorded.');for(const l of data.lots)if(!state.lots.some(x=>x.id===l.id))state.lots.push(l);persist();render();}catch(e){toast(e.message);}};
$('#send-provider').onclick=async()=>{try{const result=await api('send','POST',{to:$('#provider-to').value,body:$('#provider-body').value});toast(`Provider accepted message ${result.sid} (${result.status}); delivery not yet proven.`);}catch(e){toast(e.message);}};
function connectivity(){$('#connection').textContent=navigator.onLine?'● Conectado · AI local':'● Offline · AI local';}window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);connectivity();render();installLanguageSwitch();
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').then(()=>navigator.serviceWorker.ready).then(()=>toast('Offline cache ready. Reload once, then test airplane mode.')).catch(e=>toast('Offline cache unavailable: '+e.message));

